contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test sends some ether to c (via fallback) and then attempts to call withdrawAll.
    // On the original P, onlyOwner prevents this contract from withdrawing (so c's balance remains),
    // while the mutant M allows withdrawal by anyone causing c's balance to drop.
    function runTest(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance for test");
        // deposit into c by sending ETH to it, invoking fallback which increments depositsCount
        (bool s,) = address(c).call{value: sendAmount}("");
        require(s, "deposit failed");

        // record balance before attempted withdrawAll
        uint before = address(c).balance;

        // Attempt withdrawAll; on P this should revert for non-owner (or otherwise not change c balance),
        // on M it will succeed and reduce c's balance.
        // We capture whether it reverts by performing a low-level call.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        uint after = address(c).balance;

        // The distinguishing property: if caller is not the owner then c's balance must remain unchanged.
        // We can't directly know owner, but in P only the deployer (not this contract) is owner, so
        // for any caller that is not the owner the call should not withdraw funds. Expressed generally:
        // assert that either the call failed (ok == false) or the balance stayed the same.
        assert(ok == false || after == before);
    }

    // allow contract to receive Ether so tests can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller must be non-owner; we express that by requiring that c.owner() != msg.sender
    function run() public payable {
        require(c.owner() != msg.sender);
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On the original contract, withdrawAll should revert for non-owners; the mutant removes the restriction and will not revert.
        assert(reverted);
    }
    receive() external payable { }
}

