pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(); }

    // Fuzz parameters: amount to fund the contract and the amount to attempt to withdraw via sendMoney target (as value)
    function testFuzz_property(uint256 fundAmount, uint256 sendValue) public {
        // keep amounts in sensible ranges but wide
        fundAmount = bound(fundAmount, 1, 1 ether);
        sendValue = bound(sendValue, 0, 1 ether);

        // fund the attacker so it can forward calls if needed
        vm.deal(address(attacker), 2 ether);
        // fund the contract c with fundAmount from the test actor
        vm.deal(address(this), fundAmount);
        // send funds into the contract via fallback by calling with value
        // using this contract as sender
        (bool okFund,) = address(c).call{value: fundAmount}("");
        require(okFund, "funding failed");

        // record balance before
        uint256 before = address(c).balance;
        // We will call sendMoney with attacker as the target. The attacker simply accepts the call.
        // sendValue may be larger than contract balance; that's acceptable because sendMoney will attempt a call and may fail.

        // perform the external call from the contract to attacker
        // as sendMoney is public and onlyOwner-gated in reference, we need to call it from the owner (setUp deployer) to follow allowed path
        // c was deployed in setUp by this test contract address (owner). So calling directly is owner-invoked.
        // call sendMoney with fuzzed sendValue and target attacker
        bool sendOk;
        try c.sendMoney(address(attacker), sendValue) {
            sendOk = true;
        } catch {
            sendOk = false;
        }

        // After sendMoney completes, in the correct contract only the owner can withdrawAll; since we're owner, withdrawAll would withdraw remaining balance to owner.
        // But the mutant removed onlyOwner, allowing anyone to withdrawAll; to detect the mutant we check that a non-owner cannot reduce the contract balance by calling withdrawAll.

        // Have attacker (non-owner) attempt to call withdrawAll. If onlyOwner modifier works, this should revert; if removed, it will succeed and drain balance.
        vm.deal(address(attacker), 1); // ensure attacker has some gas-paying ETH
        vm.prank(address(attacker));
        bool attackerWithdrawOk;
        try c.withdrawAll() {
            attackerWithdrawOk = true;
        } catch {
            attackerWithdrawOk = false;
        }

        // The invariant: a non-owner (attacker) must NOT be able to successfully call withdrawAll().
        // In the reference contract this holds for all inputs; the mutant removing the onlyOwner check makes attackerWithdrawOk == true for some inputs.
        assertTrue(!attackerWithdrawOk);
    }
}

// Minimal helper: simple payable contract to receive call from C
contract Attacker {
    receive() external payable {}
}

