pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialFunding) public {
        // keep funding in a reasonable range but wide enough for fuzzing
        initialFunding = bound(initialFunding, 1, 1 ether);

        // owner is the test contract by default because c was deployed in setUp()
        // fund the contract
        vm.deal(address(this), initialFunding);
        // send funds to contract using fallback by sending empty calldata
        (bool sent, ) = address(c).call{value: initialFunding}("");
        require(sent);

        // sanity: contract has the funded balance
        assertTrue(address(c).balance == initialFunding);

        // call withdrawAll as owner (this contract)
        c.withdrawAll();

        // GENERAL RULE (single assertion): after withdrawAll, reference implementation leaves c.balance == 0
        // The mutant that calls withdraw(0) will leave c.balance == initialFunding (>0) for these inputs,
        // so this assertion will fail on the mutant for some initialFunding values.
        assertTrue(address(c).balance == 0);
    }
}

