pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an amount of ETH the owner will deposit into the contract.
    // The property: after owner funds the contract with a positive amount and then calls withdrawAll,
    // the owner's external balance must increase by exactly the funded amount (i.e., the contract is emptied to owner).
    function testFuzz_property(uint128 fundAmount) public {
        // keep fundAmount in a wide admissible domain but nonzero so the property is meaningful
        uint256 amount = bound(fundAmount, 1, type(uint128).max);

        // owner is the test contract deployer (c.owner == address(this)) by construction
        address owner = address(this);

        // give the owner enough ETH to fund the contract
        vm.deal(owner, amount + 1 ether);

        // record owner's balance before funding
        uint256 beforeOwner = owner.balance;

        // fund the contract by sending ETH to its fallback (which increments depositsCount)
        // using direct call to ensure fallback is invoked
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        // sanity: contract balance must equal the funded amount
        require(address(c).balance == amount, "contract not funded as expected");

        // Owner calls withdrawAll. This should transfer the full contract balance to owner in the correct contract.
        // Capture owner balance change via try/catch in case mutant reverts (not expected here).
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the owner's balance must have increased by exactly `amount`.
        // If the call reverted, that's still a violation for the mutant only in some cases; however
        // the correct contract should always succeed here. So assert that either the call succeeded and
        // owner's balance increased by amount, or (invariant) the contract's balance is zero and owner's increased.
        // We use a single assertTrue observing c via its balance and owner's balance change.

        uint256 afterOwner = owner.balance;
        uint256 afterContract = address(c).balance;

        // The universal property: for all admissible (positive) fund amounts, withdrawAll succeeds and transfers the whole balance
        // to the owner, so afterContract == 0 and afterOwner - beforeOwner == amount.
        assertTrue(ok && afterContract == 0 && afterOwner - beforeOwner == amount);
    }
}

