pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: an arbitrary positive amount funded by the owner into c
    function testFuzz_property(uint128 amount) public {
        // keep a wide admissible domain but require a positive funded amount
        vm.assume(amount > 0);
        // make the test owner fund the contract: the deployer (address(this)) is owner
        address owner = address(this);
        // give this contract the ETH to fund
        vm.deal(owner, uint256(amount));
        // fund c by calling fallback (send ether to contract)
        // since c.fallback is payable and increments depositsCount, send value
        (bool sent, ) = address(c).call{value: uint256(amount)}("");
        require(sent, "funding failed");

        // Confirm contract has that balance pre-withdraw
        assertTrue(address(c).balance == uint256(amount));

        // owner calls withdrawAll; for the correct contract this sends all ETH out
        // use try/catch in case of unexpected revert; we still assert on address(c).balance
        try c.withdrawAll() {
            // no-op
        } catch {
            // if it reverts, balance may remain; we still check postcondition below
        }

        // Exactly one assertion: after owner calls withdrawAll, the contract balance must be zero
        // This holds for the reference implementation for ALL admissible inputs (any positive amount funded by owner)
        // but is violated by the mutant which calls withdraw(0) (leaving a positive balance for some inputs).
        assertTrue(address(c).balance == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: caller provides an amount to send to C and an attempted withdraw amount
    // The test will: fund this test contract's balance into c via fallback by calling with value,
    // then call withdraw on c (as this contract). The invariant: if c's balance decreased after the call,
    // then msg.sender (the caller of c.withdraw) must be the owner stored in c.
    // In the original contract P this holds because withdraw is onlyOwner; in mutant M it is violated.
    function runTest(uint fundAmount, uint withdrawAmount) public payable {
        // preconditions
        require(msg.value == fundAmount, "provide fundAmount as msg.value");
        require(fundAmount > 0);

        // send funds to C so it has balance to withdraw; invoke fallback to increment depositsCount
        address(c).call{value: fundAmount}("");

        // read balance before
        uint balBefore = address(c).balance;

        // call withdraw as THIS contract (which may or may not be owner)
        c.withdraw(withdrawAmount);

        // read balance after
        uint balAfter = address(c).balance;

        // If the contract's balance decreased, then the caller of withdraw (this contract) must be owner.
        // We observe owner via public getter c.owner().
        assert(!(balAfter < balBefore) || (address(this) == c.owner()));
    }

    // allow contract to receive ETH so msg.value can be forwarded into this contract when running tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint value) public payable {
        require(caller != address(0));
        // perform the call from caller by using low-level call to C.withdraw(uint)
        // We cannot change msg.sender in this contract, so emulate external caller via call on address(c)
        // Build calldata for withdraw(uint256)
        bytes memory data = abi.encodeWithSignature("withdraw(uint256)", value);
        (bool reverted, ) = address(c).call(abi.encodePacked(data, ""));
        // The rule: if the caller is not the recorded owner, the call must revert.
        // We can read owner via its public getter c.owner()
        address owner = c.owner();
        // If caller equals owner then call may succeed; if caller != owner then call must have reverted.
        assert((caller == owner) == (!reverted));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint amount) public payable {
        require(caller != address(0));
        bool reverted;
        // Perform the call as an external caller by using call on c with abi-encoded selector.
        // We cannot change msg.sender in Solidity directly; instead we observe the behavior: if a non-owner calls withdraw it must revert on P.
        // To simulate different callers while obeying the flat-call rule, we invoke withdraw directly (msg.sender will be this test contract).
        // The distinguishing property is independent of value transfer here: only owner can succeed. We therefore assert that if this contract is not the owner, withdraw reverts.
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        // Check whether this test contract is the owner via the public getter owner()
        address owner = c.owner();
        // General rule: withdraw call should succeed iff caller is owner. Here the caller is this contract.
        assert((address(this) == owner) == (!reverted));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // call withdrawAll as caller 'caller' with provided amount funded to this test contract
    // Ensure preconditions (we need to fund c by sending Ether via fallback)
    function run(address caller, uint fundAmount) public payable {
        require(msg.sender == caller, "sender must be caller");
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // fund the target contract by calling its fallback (send Ether)
        (bool s,) = address(c).call{value: fundAmount}("");
        require(s, "funding failed");

        // record owner's address and contract balance before withdraw
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // attempt withdrawAll from this contract (msg.sender == caller)
        // Since this Solidity test contract is making the call, the only way caller is used
        // is by requiring msg.sender == caller above. Thus this call is made by 'caller'.
        c.withdrawAll();

        uint balanceAfter = address(c).balance;

        // The general rule: if the caller is NOT the recorded owner, the balance must remain unchanged.
        // That is, only the owner can reduce the contract balance via withdrawAll.
        assert((caller != ownerBefore) ? (balanceAfter == balanceBefore) : (balanceAfter == 0));
    }

    // allow receiving Ether to fund this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        bool reverted;
        // perform the call as an external caller by using low-level call to forward msg.sender
        // We simulate calls from `caller` by using call on the contract address with encoded selector.
        // Build calldata for withdraw(uint256) with value 0 (we only test permission, not amount).
        bytes memory data = abi.encodeWithSignature("withdraw(uint256)", uint256(0));
        // Make the call originate from this contract but include the intended caller address in calldata is not possible;
        // Instead we observe permission by checking that when msg.sender equals c.owner (the contract deployer) withdraw succeeds;
        // to generalize: call withdraw from this contract (which is not the owner in mutant case) and record revert.
        try c.withdraw(uint256(0)) { reverted = false; } catch { reverted = true; }
        // In the original contract, only the owner (the deployer of c) can call withdraw successfully.
        // Since this contract (InvMutTest) is not the owner of c in general, calls here should revert.
        // Thus the general rule: if this contract is not c.owner(), then withdraw call here reverts.
        // We cannot call c.owner() if it weren't public, but C defines owner as public so we can read it.
        address owner = c.owner();
        bool amOwner = (owner == address(this));
        // Assert that withdraw reverts iff this contract is not the recorded owner
        assert(reverted == (!amOwner));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0)); // callers used in tests are real addresses
        bool reverted;
        // Call withdraw as "caller" by using low-level call to set msg.sender
        (bool ok, bytes memory) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", 0));
        // The above call originates from this contract, so treat 'caller' as a parameter only.
        // We instead express the property over the provided 'caller' parameter: on original C only calls from non-zero addresses may succeed; mutant requires zero address and thus will revert for all non-zero callers.
        // Since we cannot change msg.sender here, we capture the distinguishing condition as a relation between the input 'caller' and revert flag of this contract's attempt (which behaves like a non-zero caller).
        try c.withdraw(0) { reverted = false; } catch { reverted = true; }
        // General rule: if the provided caller is non-zero then withdraw invoked by a non-zero caller (this contract) should NOT revert in the original; thus for any non-zero caller reverted must be false.
        assert(!(caller != address(0)) || reverted == false);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No special precondition needed: ensure caller is a regular externally owned account (can't be address(0)).
        // Call withdraw and record whether it reverted.
        bool reverted;
        try c.withdraw(0) { reverted = false; } catch { reverted = true; }
        // In the original contract, non-zero callers (normal EOAs) are allowed by onlyOwner and withdraw should not revert.
        assert(reverted == false);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // Require that the caller is a regular externally owned account and matches the stored c.owner,
        // so the call to withdraw(0) is made by the contract owner (ensuring original contract does not revert).
        require(msg.sender != address(0) && msg.sender == c.owner());
        // Call withdraw and record whether it reverted.
        bool reverted;
        try c.withdraw(0) { reverted = false; } catch { reverted = true; }
        // In the original contract, non-zero callers (normal EOAs) are allowed by onlyOwner and withdraw should not revert.
        assert(reverted == false);
    }
    receive() external payable { }
}

