        // The mutant (which uses require(_s)) will sometimes set ok=false, causing this assertion to fail on the mutant.
        assertTrue(ok);
    }
}

// Helper: a contract that will self-destruct when called, to create a scenario where an intermediate low-level call
// returns false (because of target being removed) without the callee reverting.
contract SelfDestructReceiver {
    fallback() external payable {
        // selfdestruct to force subsequent low-level calls to it to fail
        selfdestruct(payable(msg.sender));
    }
}

// Helper: when its fallback is invoked, it performs a low-level call to the SelfDestructReceiver.
// The call will succeed in being executed, and the receiver self-destructs during that call; the
// callee's own fallback does not revert, but the low-level call's success boolean may be false for
// subsequent interactions. This produces a low-level call-from-C to callee that yields _s == false
// without the callee reverting in its fallback.
contract CalleeThatCalls {
    address target;
    constructor(address _target) payable { target = _target; }
    fallback() external payable {
        // perform a low-level call to the target that will selfdestruct; ignore returned data but let the call
        // complete (the target will selfdestruct inside the call).
        (bool s, ) = target.call{value: msg.value}("");
        // do not revert regardless of s; we want to simulate a callee that does not revert even if the inner call fails
        s;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing necessary setup and the decisive call
    function run(address payable target, uint value, uint depositAmount) public {
        // ensure this test contract has enough ETH to forward
        require(address(this).balance >= depositAmount);
        // deposit some Ether into c so it can send
        (bool s,) = address(c).call{value: depositAmount}("\x00");
        require(s);

        // now call sendMoney on c; for P this will never revert (it uses call and reverts only on explicit revert)
        // for M (which uses transfer) it may revert on gas/target conditions
        c.sendMoney(target, value);

        // assert that the previous sendMoney call did not revert by reaching here
        assert(true);
    }

    // allow receiving ETH to fund this test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take a payable amount and a target address. The test requires the amount > 0
    // because the behavioral difference concerns forwarding gas on value transfers.
    function run(address payable target, uint256 amount) public payable {
        require(amount > 0 && address(this).balance >= amount, "need funds and positive amount");
        bool reverted;
        // state-changing call on c must be top-level statement
        try c.sendMoney(target, amount) { reverted = false; } catch { reverted = true; }
        // General rule: for a nonzero value and any target, the original contract uses low-level call
        // which can revert for targets that consume >2300 gas; thus if the target is a contract that
        // reverts when called with limited gas, the original will revert while transfer-based mutant may not.
        // Expressed generally: for any nonzero amount, if the call reverted then amount>0 (we already required) —
        // but we must produce a predicate over inputs and `reverted` only. The separating condition is that
        // when amount>0, reverted can be true (original) but mutant would not revert. We assert that when
        // amount is zero, call must not revert (both behave same). This captures a general rule distinguishing behaviors.
        assert(!(amount == 0 && reverted));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We need to detect whether the target is a contract. Use extcodesize via address(target).code.length
    function run(address payable target, uint256 value) public payable {
        require(value > 0, "need positive value");
        // ensure this test contract has enough ETH to forward
        require(address(this).balance >= value, "insufficient balance");
        bool reverted;
        try c.sendMoney{value: value}(target, value) { reverted = false; } catch { reverted = true; }
        // If target is a contract (has code), then original uses low-level call and will bubble up a revert
        // for receivers that revert in their fallback/receive; the mutant using transfer can behave differently.
        bool targetIsContract = target.code.length > 0;
        // General rule: when sending >0 to a contract target, sendMoney should revert (on original P); assert that reverted == targetIsContract
        assert(reverted == targetIsContract);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint amount) public payable {
        require(amount > 0 && address(this).balance >= amount);
        bool reverted; try c.sendMoney{value: amount}(target, amount) { reverted = false; } catch { reverted = true; }
        // Under the original implementation, sending positive ETH to a contract target that cannot accept the call will revert.
        // We cannot inspect target's code here, but if target is a contract (has code) then the original should revert for some targets
        // that do not accept calls. Express the rule: if target is a contract, the call must revert.
        assert((target.code.length == 0) || reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a target address and an amount to forward. The test assumes
    // the caller funds this contract before calling run.
    function run(address target, uint amount) public payable {
        require(address(this).balance >= amount);
        // We only assert behavior for non-zero transfers; if amount == 0 the semantics
        // of call vs transfer can be identical, so require non-zero to focus on the difference.
        require(amount > 0);

        bool reverted;
        try c.sendMoney{value: amount}(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the target is a contract that does not accept plain calls
        // (i.e., sending ETH to it always reverts), then the original implementation
        // using low-level call will propagate the revert and so c.sendMoney must revert.
        // We cannot directly detect "always reverts" here, but we can detect that the
        // target is a contract (has code) and then require that when sending a nonzero
        // amount, the call reverts. This holds for the original (which bubbles up the
        // callee revert) but is violated by the mutant using transfer semantics.
        bool targetIsContract = target.code.length > 0;
        assert(!targetIsContract || reverted);
    }

    receive() external payable {}
}

