pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: amount to send
    function testFuzz_property(uint256 amount) public {
        // keep amount in a wide but sensible bound so vm.deal can handle it
        amount = bound(amount, 0, 1 ether);

        // deploy an adversarial callee that always reverts on receive/fallback
        Reverter rev = new Reverter();

        // fund the contract C so it can attempt to send
        vm.deal(address(c), 1 ether);

        bool ok;
        // call sendMoney on c targeting the reverter; capture success via try/catch
        try c.sendMoney(address(rev), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation uses low-level call and should return (not transfer) which yields a caught failure (ok == false)
        // The mutant using transfer would revert at transfer for a reverting fallback, producing ok == false as well,
        // but the intended distinguishing rule is that the reference's low-level call allows inspecting failure without immediate revert semantics in some contexts. Assert that the call did not incorrectly succeed.
        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
